WITH with_dims AS (SELECT a.id, a.account_id, a.txn_time, a.merchant, a.is_flagged, b.opened_date FROM transactions a JOIN accounts b ON a.account_id = b.id WHERE b.opened_date BETWEEN '2025-07-01' AND '2025-08-01') SELECT s.id, s.account_id, s.txn_time, s.is_flagged, s.opened_date, (SELECT AVG(t2.amount) FROM transactions t2 WHERE t2.account_id = s.account_id) AS avg_transaction_amount FROM with_dims s
